async function checkDb(req, res, next) { if (!dbReady) return res.status(503).send('<div style="text-align:center;padding:100px"><h1>Starting...</h1><p><a href="' + req.url + '">Refresh</a></p></div>'); next(); }
const requireAuth = (req, res, next) => { if (!req.session.user) return res.redirect('/login'); req.tenant = req.session.tenant; req.tenantId = req.session.tenant.id; req.lang = req.query.lang || detectLang(req); next(); };
const requireRole = (role) => (req, res, next) => { if (!req.session.user || req.session.user.role !== role) return res.status(403).send(renderPage('Forbidden', '<div class="card"><h1>403</h1></div>', { tenant_name: req.tenant ? req.tenant.name : null })); next(); };
const requireStaff = (req, res, next) => { if (!req.session.user || !['admin', 'super_admin', 'teacher'].includes(req.session.user.role)) return res.status(403).send(renderPage('Forbidden', '<div class="card"><h1>403</h1></div>', { tenant_name: req.tenant ? req.tenant.name : null })); next(); };
const requireAdmin = (req, res, next) => { if (!req.session.user || !['admin', 'super_admin'].includes(req.session.user.role)) return res.status(403).send(renderPage('Forbidden', '<div class="card"><h1>403 Admins Only</h1></div>', { tenant_name: req.tenant ? req.tenant.name : null })); next(); };

async function sendSMS(phone, message) { if (SMS_CONFIG.apiKey === 'demo') { console.log('[SMS DEMO] ' + phone + ': ' + message); return; } try { await axios.post('https://api.africastalking.com/version1/messaging', 'username=' + SMS_CONFIG.username + '&to=' + phone + '&message=' + encodeURIComponent(message) + '&from=' + SMS_CONFIG.senderId, { headers: { 'apiKey': SMS_CONFIG.apiKey, 'Content-Type': 'application/x-www-form-urlencoded' } }); } catch (e) { console.error('SMS Error:', e.message); } }
async function sendWhatsApp(phone, message) { if (WHATSAPP_CONFIG.token === 'demo') { console.log('[WA DEMO] ' + phone + ': ' + message); return; } try { await axios.post('https://graph.facebook.com/v18.0/' + WHATSAPP_CONFIG.phoneId + '/messages', { messaging_product: 'whatsapp', to: phone, text: { body: message } }, { headers: { 'Authorization': 'Bearer ' + WHATSAPP_CONFIG.token } }); } catch (e) { console.error('WA Error:', e.message); } }
async function sendBulkSMS(tenantId, message) { const { rows } = await pool.query("SELECT DISTINCT guardian_phone FROM students WHERE tenant_id=$1 AND guardian_phone IS NOT NULL AND guardian_phone != ''", [tenantId]); for (const r of rows) { await sendSMS(r.guardian_phone, message); await new Promise(res => setTimeout(res, 200)); } }

async function addBonus(userId, tenantId, amount, type, description, metaData) { metaData = metaData || {}; await pool.query('INSERT INTO bonus_earnings (user_id, tenant_id, amount, type, description, metadata) VALUES ($1,$2,$3,$4,$5,$6)', [userId, tenantId, amount, type, description, JSON.stringify(metaData)]); await pool.query('UPDATE wallets SET balance = balance + $1, updated_at=NOW() WHERE user_email=$2', [amount, userId]); }
async function addDevCommission(amount, type, description, referenceId) { await pool.query('INSERT INTO developer_revenue (amount, type, description, reference_id) VALUES ($1,$2,$3,$4)', [amount, type, description, referenceId]); await pool.query('UPDATE platform_wallet SET balance = balance + $1, updated_at=NOW() WHERE id=1', [amount]); }

