app.post('/api/subscribe', requireAuth, checkDb, async (req, res) => {
  try {
    await pool.query('INSERT INTO push_subscriptions (user_email, endpoint, keys) VALUES ($1,$2,$3) ON CONFLICT DO NOTHING', [req.session.user.email, req.body.endpoint, JSON.stringify(req.body.keys)]);
    res.json({ success: true });
  } catch (e) { res.status(500).json({ error: 'Failed' }); }
});

async function sendPushToUser(email, title, body, data) {
  data = data || {};
  const subs = await pool.query('SELECT endpoint, keys FROM push_subscriptions WHERE user_email=$1', [email]);
  for (const sub of subs.rows) {
    try {
      await webpush.sendNotification({ endpoint: sub.endpoint, keys: sub.keys }, JSON.stringify({ title, body, data }));
    } catch (e) { console.error('Push failed:', e.message); }
  }
}

async function sendPushToTenant(tenantId, title, body, role) {
  let query = 'SELECT DISTINCT u.email FROM users u JOIN push_subscriptions p ON u.email=p.user_email WHERE u.tenant_id=$1';
  let params = [tenantId];
  if (role) { query += ' AND u.role=$2'; params.push(role); }
  const users = await pool.query(query, params);
  for (const u of users.rows) await sendPushToUser(u.email, title, body);
}

app.get('/app/referrals', requireAuth, checkDb, async (req, res) => {
  const stats = await pool.query("SELECT r.referred_email, r.signup_date, u.full_name, u.role, t.name as school, COALESCE(SUM(b.amount),0) as earned FROM referral_stats r LEFT JOIN users u ON r.referred_email = u.email LEFT JOIN tenants t ON u.tenant_id = t.id LEFT JOIN bonus_earnings b ON b.description LIKE 'Referred ' || r.referred_email || '%' AND b.user_id = $1 GROUP BY r.referred_email, r.signup_date, u.full_name, u.role, t.name ORDER BY r.signup_date DESC", [req.session.user.email]);
  const totalEarned = stats.rows.reduce((sum, r) => sum + parseFloat(r.earned), 0);
  const link = 'https://' + req.headers.host + '/signup?ref=' + req.session.user.email;
  const tableRows = stats.rows.map(r => '<tr><td>' + esc(r.full_name || r.referred_email) + '</td><td>' + esc(r.school || '-') + '</td><td>' + esc(r.role) + '</td><td>' + new Date(r.signup_date).toLocaleDateString() + '</td><td class="badge badge-green">+UGX ' + r.earned + '</td></tr>').join('');
  res.send(renderPage('Referrals', '<div class="hero" style="padding:30px"><h1>Referral Earnings</h1><div class="stat-num" style="color:white;-webkit-text-fill-color:white">UGX ' + totalEarned.toLocaleString() + '</div></div><div class="card"><h3>Share Link</h3><input value="' + link + '" readonly id="refLink"><button class="btn" onclick="navigator.clipboard.writeText(document.getElementById(\'refLink\').value)">Copy</button></div><div class="card"><h3>Referred Users (' + stats.rows.length + ')</h3><table><thead><tr><th>Name</th><th>School</th><th>Role</th><th>Date</th><th>Earned</th></tr></thead><tbody>' + (tableRows || '<tr><td colspan="5">No referrals yet</td></tr>') + '</tbody></table></div>', { tenant_name: req.tenant.name }, false, req.lang));
});

