app.get('/games/play/:id', requireAuth, checkDb, async (req, res) => { res.send(renderPage('Playing', '<div class="card" style="max-width:600px;margin:40px auto"><h1>Math Quiz</h1><div id="quiz-area" style="text-align:center;margin:20px 0"><div style="font-size:36px" id="question"></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:20px"><button class="btn" onclick="checkAnswer(this)" id="ans1"></button><button class="btn" onclick="checkAnswer(this)" id="ans2"></button><button class="btn" onclick="checkAnswer(this)" id="ans3"></button><button class="btn" onclick="checkAnswer(this)" id="ans4"></button></div></div><div id="result" style="display:none;text-align:center"><h2>Won!</h2><p class="badge badge-green" style="font-size:18px">+30 UGX</p><a href="/games" class="btn" style="margin-top:20px">Back</a></div></div></div><script>let q=[],idx=0;for(let i=0;i<5;i++){let a=Math.floor(Math.random()*20)+1,b=Math.floor(Math.random()*20)+1,o=[\'+\',\'-\',\'×\'][Math.floor(Math.random()*3)],ans=o===\'+\'?a+b:o===\'-\'?a-b:a*b;q.push({q:a+\' \'+o+\' \'+b+\' = ?\',ans});}function showQ(){if(idx>=5){document.getElementById(\'quiz-area\').style.display=\'none\';document.getElementById(\'result\').style.display=\'block\';fetch(\'/bonus/claim/game/quiz\').catch(()=>{});return;}let c=q[idx];document.getElementById(\'question\').textContent=c.q;let opts=[c.ans];while(opts.length<4){let w=c.ans+Math.floor(Math.random()*20)-10;if(!opts.includes(w))opts.push(w);}opts.sort(()=>Math.random()-0.5);for(let i=1;i<=4;i++){document.getElementById(\'ans\'+i).textContent=opts[i-1];document.getElementById(\'ans\'+i).dataset.ans=opts[i-1];}}function checkAnswer(btn){idx++;showQ();}showQ();</script>', { tenant_name: req.tenant.name }, false, req.lang)); });
