app.get('/marketplace', async (req, res) => { const { rows } = await pool.query('SELECT p.*, t.name as school_name FROM marketplace_products p JOIN tenants t ON p.tenant_id=t.id WHERE p.approved=true ORDER BY p.id DESC LIMIT 20'); const cards = rows.map(p => '<div class="card" style="padding:0;overflow:hidden"><img src="' + (p.image_url || 'https://via.placeholder.com/200') + '" class="card-img"><div style="padding:16px"><span class="badge badge-blue" style="margin-bottom:8px">By ' + esc(p.school_name) + '</span><h4>' + esc(p.name) + '</h4><div class="stat-num" style="font-size:24px;margin:12px 0">UGX ' + p.price + '</div><a href="/marketplace/buy/' + p.id + '" class="btn btn-green" style="width:100%">Buy Now</a></div></div>').join(''); res.send(renderPage('Marketplace', '<div class="hero" style="padding:30px"><h1>Marketplace</h1>' + (req.session.user ? '<a href="/marketplace/sell" class="btn btn-purple" style="margin-top:12px">Sell Product</a>' : '') + '</div><div class="grid">' + (cards || '<div class="card"><p>No products yet</p></div>') + '</div>', null, true)); });
app.get('/marketplace/sell', requireAuth, requireAdmin, (req, res) => { res.send(renderPage('Sell', '<div class="card" style="max-width:500px"><h1>List Product</h1><p style="color:#64748b">10% commission on sales</p><form method="POST" action="/marketplace/sell"><input name="name" placeholder="Product Name" required><input name="price" type="number" placeholder="Price UGX" required><input name="image_url" placeholder="Image URL"><textarea name="description" placeholder="Description" rows="3"></textarea><button class="btn btn-green" style="width:100%">Submit</button></form></div>', { tenant_name: req.tenant.name }, false, req.lang)); });
app.post('/marketplace/sell', requireAuth, requireAdmin, checkDb, async (req, res) => { await pool.query('INSERT INTO marketplace_products (tenant_id, name, price, image_url, description, approved) VALUES ($1,$2,$3,$4,$5,$6)', [req.tenantId, req.body.name, req.body.price, req.body.image_url, req.body.description, false]); res.send(renderPage('Submitted', '<div class="card" style="text-align:center"><h1>Submitted!</h1><a href="/marketplace" class="btn">View</a></div>', { tenant_name: req.tenant.name }, false, req.lang)); });
app.get('/marketplace/buy/:id', async (req, res) => { const p = (await pool.query('SELECT * FROM marketplace_products WHERE id=$1', [req.params.id])).rows[0]; if (!p) return res.status(404).send('Not found'); res.send(renderPage('Buy', '<div class="card" style="max-width:500px;margin:40px auto"><h1>Buy ' + esc(p.name) + '</h1><p class="stat-num" style="font-size:24px">UGX ' + p.price + '</p><form method="POST" action="/marketplace/buy/' + p.id + '"><input name="phone" placeholder="MoMo" required><button class="btn btn-green" style="width:100%">Pay</button></form></div>', null, true)); });
app.post('/marketplace/buy/:id', checkDb, async (req, res) => { const p = (await pool.query('SELECT * FROM marketplace_products WHERE id=$1', [req.params.id])).rows[0]; if (!p) return res.status(404).send('Not found'); const ref = 'MKT-' + Date.now(); await pool.query('INSERT INTO payment_requests (tenant_id, amount, phone, reference, status) VALUES ($1,$2,$3,$4,$5)', [p.tenant_id, p.price, req.body.phone, ref, 'pending']); await addDevCommission(Math.round(p.price * DEV_COMMISSION.marketplace), 'marketplace', 'Marketplace: ' + p.name, ref); res.send(renderPage('Success', '<div class="card" style="text-align:center"><h1>Prompt Sent!</h1></div>', null, true)); });

app.get('/app', requireAuth, checkDb, async (req, res) => { try { const s = await pool.query('SELECT COUNT(*)::int AS c FROM students WHERE tenant_id=$1', [req.tenantId]); const f = await pool.query('SELECT COALESCE(SUM(paid),0)::numeric AS t FROM fees WHERE tenant_id=$1', [req.tenantId]); const a = await pool.query("SELECT COUNT(*)::int AS c FROM attendance WHERE tenant_id=$1 AND date=CURRENT_DATE AND status='present'", [req.tenantId]); const w = (await pool.query('SELECT balance FROM wallets WHERE user_email=$1', [req.session.user.email])).rows[0] || { balance: 0 }; res.send(renderPage('Dashboard', '<div class="stats"><div class="stat-card"><div style="font-size:24px;margin-bottom:8px">🎓</div><div>Students</div><div class="stat-num">' + s.rows[0].c + '</div></div><div class="stat-card"><div style="font-size:24px;margin-bottom:8px">💰</div><div>Fees</div><div class="stat-num">UGX ' + f.rows[0].t + '</div></div><div class="stat-card"><div style="font-size:24px;margin-bottom:8px">✅</div><div>Present</div><div class="stat-num">' + a.rows[0].c + '</div></div><div class="stat-card"><div style="font-size:24px;margin-bottom:8px">🎁</div><div>Rewards</div><div class="stat-num">UGX ' + w.balance + '</div></div></div><div class="card"><h1>Quick Actions</h1><div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:16px"><a href="/app/students/add" class="btn btn-green">Add Student</a><a href="/app/fees/add" class="btn">Record Fee</a><a href="/app/attendance/mark" class="btn">Attendance</a><a href="/app/grades/add" class="btn">Grades</a><a href="/app/timetable/add" class="btn btn-orange">Timetable</a><a href="/app/exams/add" class="btn btn-purple">Exams</a><a href="/bonus" class="btn btn-purple">Rewards</a></div></div>', { tenant_name: req.tenant.name }, false, req.lang)); } catch(e){res.status(500).send("Error");} });

app.get('/app/fees', requireAuth, checkDb, async (req, res) => { const { rows } = await pool.query('SELECT f.*, s.name as sn FROM fees f JOIN students s ON f.student_id=s.id WHERE f.tenant_id=$1 ORDER BY f.id DESC LIMIT 50', [req.tenantId]); const t = rows.map(f => '<tr><td>' + esc(f.sn) + '</td><td>' + f.amount + '</td><td>' + f.paid + '</td><td>' + esc(f.term) + '</td><td>' + esc(f.payment_method) + '</td></tr>').join(''); res.send(renderPage('Fees', '<div class="card"><h1>Fees</h1><a href="/app/fees/add" class="btn btn-green">Record</a><table style="margin-top:16px"><thead><tr><th>Student</th><th>Due</th><th>Paid</th><th>Term</th><th>Method</th></tr></thead><tbody>' + (t || '<tr><td colspan="5">None</td></tr>') + '</tbody></table></div>', { tenant_name: req.tenant.name }, false, req.lang)); });
app.get('/app/fees/add', requireAuth, requireStaff, checkDb, async (req, res) => { const s = await pool.query('SELECT id, name FROM students WHERE tenant_id=$1', [req.tenantId]); const opts = s.rows.map(x => '<option value="' + x.id + '">' + esc(x.name) + '</option>').join(''); res.send(renderPage('Record Fee', '<div class="card" style="max-width:500px"><h1>Record Fee</h1><form method="POST" action="/app/fees/add"><select name="student_id" required><option value="">Select</option>' + opts + '</select><input name="amount" type="number" required><input name="paid" type="number" required><input name="term"><input name="year" type="number" value="' + new Date().getFullYear() + '"><select name="payment_method"><option>Cash</option><option>MoMo</option><option>Bank</option></select><button class="btn btn-green" style="width:100%">Save</button></form></div>', { tenant_name: req.tenant.name }, false, req.lang)); });
app.post('/app/fees/add', requireAuth, requireStaff, checkDb, async (req, res) => { try { const { student_id, amount, paid, term, year, payment_method } = req.body; const s = (await pool.query('SELECT * FROM students WHERE id=$1', [student_id])).rows[0]; await pool.query('INSERT INTO fees (tenant_id, student_id, amount, paid, term, year, payment_method) VALUES ($1,$2,$3,$4,$5,$6,$7)', [req.tenantId, student_id, amount, paid, term, year, payment_method]); await pool.query('UPDATE students SET balance = balance - $1 WHERE id=$2', [paid, student_id]); if (s.guardian_phone) { await sendSMS(s.guardian_phone, 'Payment of UGX ' + paid + ' received for ' + s.name + '. Balance: UGX ' + (s.balance - paid)); const parent = await pool.query("SELECT email FROM users WHERE phone=$1 AND role='parent'", [s.guardian_phone]); if (parent.rows[0]) await sendPushToUser(parent.rows[0].email, 'Fee Payment Received', 'UGX ' + paid + ' for ' + s.name); } res.redirect('/app/fees'); } catch(e){res.status(500).send("Error");} });

app.get('/app/attendance', requireAuth, checkDb, async (req, res) => { const { rows } = await pool.query("SELECT a.*, s.name FROM attendance a JOIN students s ON a.student_id=s.id WHERE a.tenant_id=$1 AND a.date=CURRENT_DATE", [req.tenantId]); const t = rows.map(a => '<tr><td>' + esc(a.name) + '</td><td><span class="badge ' + (a.status === 'present' ? 'badge-green' : 'badge-red') + '">' + a.status + '</span></td></tr>').join(''); res.send(renderPage('Attendance', '<div class="card"><h1>Today</h1><a href="/app/attendance/mark" class="btn btn-green">Mark</a><table style="margin-top:16px"><thead><tr><th>Student</th><th>Status</th></tr></thead><tbody>' + (t || '<tr><td colspan="2">None</td></tr>') + '</tbody></table></div>', { tenant_name: req.tenant.name }, false, req.lang)); });
app.get('/app/attendance/mark', requireAuth, requireStaff, checkDb, async (req, res) => { const s = await pool.query('SELECT id, name FROM students WHERE tenant_id=$1', [req.tenantId]); const cbs = s.rows.map(x => '<label style="display:block;margin:8px 0"><input type="checkbox" name="p_' + x.id + '" checked> ' + esc(x.name) + '</label>').join(''); res.send(renderPage('Mark', '<div class="card" style="max-width:500px"><h1>Mark Attendance</h1><form method="POST" action="/app/attendance/mark">' + cbs + '<button class="btn btn-green" style="width:100%;margin-top:16px">Save</button></form></div>', { tenant_name: req.tenant.name }, false, req.lang)); });
app.post('/app/attendance/mark', requireAuth, requireStaff, checkDb, async (req, res) => { try { const s = await pool.query('SELECT id FROM students WHERE tenant_id=$1', [req.tenantId]); await pool.query("DELETE FROM attendance WHERE tenant_id=$1 AND date=CURRENT_DATE", [req.tenantId]); for (const x of s.rows) { await pool.query('INSERT INTO attendance (tenant_id, student_id, date, status) VALUES ($1,$2,CURRENT_DATE,$3)', [req.tenantId, x.id, req.body['p_' + x.id] ? 'present' : 'absent']); } res.redirect('/app/attendance'); } catch(e){res.status(500).send("Error");} });
app.get('/app/attendance/stats', requireAuth, checkDb, async (req, res) => { const attData = await pool.query("SELECT s.class, COUNT(*) FILTER (WHERE status='present') as present, COUNT(*) as total FROM attendance a JOIN students s ON a.student_id=s.id WHERE a.tenant_id=$1 AND a.date > NOW() - INTERVAL '30 days' GROUP BY s.class ORDER BY s.class", [req.tenantId]); const rows = attData.rows.map(r => { const pct = r.total > 0 ? Math.round((r.present / r.total) * 100) : 0; return '<tr><td>' + esc(r.class || 'Unassigned') + '</td><td>' + r.present + '/' + r.total + '</td><td style="width:40%"><div style="background:#e2e8f0;border-radius:20px;height:24px"><div style="background:' + (pct > 75 ? '#16a34a' : pct > 50 ? '#f59e0b' : '#dc2626') + ';width:' + pct + '%;height:100%;border-radius:20px;display:flex;align-items:center;color:white;font-size:11px;font-weight:bold">' + pct + '%</div></div></td></tr>'; }).join(''); res.send(renderPage('Analytics', '<div class="card"><h1>Attendance (30 Days)</h1><table style="margin-top:16px"><thead><tr><th>Class</th><th>Present/Total</th><th>Rate</th></tr></thead><tbody>' + rows + '</tbody></table></div>', { tenant_name: req.tenant.name }, false, req.lang)); });

