app.get('/app/students', requireAuth, checkDb, async (req, res) => { const { rows } = await pool.query('SELECT * FROM students WHERE tenant_id=$1 ORDER BY id DESC', [req.tenantId]); const t = rows.map(s => '<tr><td>' + esc(s.name) + '</td><td>' + esc(s.class) + '</td><td>' + esc(s.guardian_phone) + '</td><td>UGX ' + s.balance + '</td><td><a href="/app/students/report/' + s.id + '" class="btn" style="font-size:12px;padding:8px">Report</a> <a href="/app/fees/add?student_id=' + s.id + '" class="btn" style="font-size:12px;padding:8px">Pay</a> <a href="/app/students/edit/' + s.id + '" class="btn btn-orange" style="font-size:12px;padding:8px">Edit</a> <a href="/app/students/delete/' + s.id + '" class="btn btn-red" style="font-size:12px;padding:8px" onclick="return confirm(\'Delete?\')">Del</a></td></tr>').join(''); res.send(renderPage('Students', '<div class="card"><h1>Students</h1><div style="display:flex;gap:8px;margin-bottom:16px"><a href="/app/students/add" class="btn btn-green">Add</a><a href="/app/students/bulk" class="btn btn-purple">Bulk CSV</a><a href="/app/students/export" class="btn btn-orange">Export</a></div><table style="margin-top:16px"><thead><tr><th>Name</th><th>Class</th><th>Phone</th><th>Balance</th><th>Action</th></tr></thead><tbody>' + (t || '<tr><td colspan="5">None</td></tr>') + '</tbody></table></div>', { tenant_name: req.tenant.name }, false, req.lang)); });
