app.get('/app/students/report/:id', requireAuth, checkDb, async (req, res) => { try { const s = (await pool.query('SELECT * FROM students WHERE id=$1 AND tenant_id=$2', [req.params.id, req.tenantId])).rows[0]; if (!s) return res.status(404).send('Not found'); const g = await pool.query('SELECT * FROM grades WHERE student_id=$1 ORDER BY year DESC', [req.params.id]); const f = await pool.query('SELECT * FROM fees WHERE student_id=$1 ORDER BY year DESC', [req.params.id]); const a = await pool.query("SELECT COUNT(*) FILTER (WHERE status='present') as p, COUNT(*) as t FROM attendance WHERE student_id=$1", [req.params.id]); const pct = a.rows[0].t > 0 ? Math.round((a.rows[0].p / a.rows[0].t) * 100) : 0; res.send(renderPage('Report', '<div class="card" style="text-align:center"><h1>' + esc(req.tenant.name) + '</h1><h2>REPORT CARD</h2><p><strong>Name:</strong> ' + esc(s.name) + ' | <strong>Class:</strong> ' + esc(s.class) + ' | <strong>Balance:</strong> UGX ' + s.balance + '</p><p><strong>Attendance:</strong> ' + pct + '% (' + a.rows[0].p + '/' + a.rows[0].t + ' days)</p></div><div class="card"><h3>Academics</h3><table><thead><tr><th>Subject</th><th>Score</th><th>Term</th><th>Year</th></tr></thead><tbody>' + (g.rows.map(x => '<tr><td>' + esc(x.subject) + '</td><td>' + x.score + '</td><td>' + esc(x.term) + '</td><td>' + x.year + '</td></tr>').join('') || '<tr><td colspan="4">No grades</td></tr>') + '</tbody></table></div><div class="card"><h3>Fees</h3><table><thead><tr><th>Term</th><th>Due</th><th>Paid</th><th>Balance</th></tr></thead><tbody>' + (f.rows.map(x => '<tr><td>' + esc(x.term) + ' ' + x.year + '</td><td>' + x.paid + '</td><td>' + (x.amount - x.paid) + '</td></tr>').join('') || '<tr><td colspan="4">No fees</td></tr>') + '</tbody></table></div><div class="card" style="text-align:center"><button onclick="window.print()" class="btn btn-green">Print Report Card</button></div>', { tenant_name: req.tenant.name }, false, req.lang)); } catch(e){res.status(500).send("Error");} });
