app.get('/learning/live/join/:id', requireAuth, checkDb, async (req, res) => {
  const cls = (await pool.query('SELECT * FROM live_classes WHERE id=$1', [req.params.id])).rows[0];
  if (!cls) return res.status(404).send('Not found');
  const paid = await pool.query('SELECT id FROM class_payments WHERE class_id=$1 AND student_email=$2 AND status=\'success\'', [cls.id, req.session.user.email]);
  const isTeacher = cls.teacher_email === req.session.user.email;
  if (!paid.rows[0] && !isTeacher) {
    return res.send(renderPage('Payment Required', '<div class="card" style="max-width:500px;margin:40px auto;text-align:center"><h1>Join ' + esc(cls.title) + '</h1><p>Teacher: ' + esc(cls.teacher_email) + '</p><div class="stat-num" style="margin:20px 0">UGX ' + cls.price + '</div><form method="POST" action="/learning/live/pay/' + cls.id + '"><input name="phone" placeholder="MoMo Number" required><button class="btn btn-green" style="width:100%">Pay & Join</button></form></div>', { tenant_name: req.tenant.name }, false, req.lang));
  }
  res.send(renderPage(cls.title, '<div class="card" style="padding:0;overflow:hidden"><div style="background:#1e293b;color:white;padding:16px"><h2>' + esc(cls.title) + '</h2><p>' + esc(cls.subject) + ' - ' + esc(cls.class) + '</p><p>👨‍🏫 ' + esc(cls.teacher_email) + '</p></div><iframe src="https://meet.jit.si/' + cls.jitsi_room + '" style="width:100%;height:600px;border:0" allow="camera;microphone;fullscreen"></iframe></div>', { tenant_name: req.tenant.name }, false, req.lang));
});
app.post('/learning/live/pay/:id', requireAuth, checkDb, async (req, res) => {
  const cls = (await pool.query('SELECT * FROM live_classes WHERE id=$1', [req.params.id])).rows[0];
  if (!cls) return res.status(404).send('Not found');
  const ref = 'CLASS-' + Date.now();
  const commission = Math.round(cls.price * DEV_COMMISSION.live_class);
  const teacherEarn = cls.price - commission;
  await pool.query('INSERT INTO class_payments (class_id, student_email, amount, phone, reference, status) VALUES ($1,$2,$3,$4,$5,$6)', [cls.id, req.session.user.email, cls.price, req.body.phone, ref, 'pending']);
  await addDevCommission(commission, 'live_class', 'Live class: ' + cls.title, ref);
  await addBonus(cls.teacher_email, cls.tenantId, teacherEarn, 'teaching', 'Taught: ' + cls.title);
  if (MOMO_CONFIG.apiKey === 'demo') { await pool.query('UPDATE class_payments SET status=$1 WHERE reference=$2', ['success', ref]); return res.redirect('/learning/live/join/' + cls.id); }
  res.send(renderPage('Processing', '<div class="card" style="text-align:center"><h1>📱 Check Phone for MoMo</h1></div>', null, true));
});

app.get('/app/analytics', requireAuth, requireAdmin, checkDb, async (req, res) => {
  const feeData = await pool.query("SELECT DATE_TRUNC('month', created_at) as month, SUM(paid) as total FROM fees WHERE tenant_id=$1 AND created_at > NOW() - INTERVAL '6 months' GROUP BY month ORDER BY month", [req.tenantId]);
  const attData = await pool.query("SELECT s.class, COUNT(*) FILTER (WHERE status='present') as present, COUNT(*) as total FROM attendance a JOIN students s ON a.student_id=s.id WHERE a.tenant_id=$1 AND a.date > NOW() - INTERVAL '30 days' GROUP BY s.class ORDER BY s.class", [req.tenantId]);
  const topStudents = await pool.query("SELECT s.name, s.class, AVG(g.score) as avg_score, COUNT(g.id) as exams FROM students s JOIN grades g ON s.id=g.student_id WHERE s.tenant_id=$1 GROUP BY s.id, s.name, s.class HAVING COUNT(g.id) > 0 ORDER BY avg_score DESC LIMIT 10", [req.tenantId]);
  const feeLabels = feeData.rows.map(r => new Date(r.month).toLocaleDateString('en-US', { month: 'short' }));
  const attRows = attData.rows.map(r => { const pct = r.total > 0 ? Math.round((r.present / r.total) * 100) : 0; return '<tr><td>' + esc(r.class || 'Unassigned') + '</td><td>' + r.present + '/' + r.total + '</td><td style="width:40%"><div style="background:#e2e8f0;border-radius:20px;height:24px"><div style="background:' + (pct > 75 ? '#16a34a' : pct > 50 ? '#f59e0b' : '#dc2626') + ';width:' + pct + '%;height:100%;border-radius:20px;display:flex;align-items:center;color:white;font-size:11px;font-weight:bold">' + pct + '%</div></div></td></tr>'; }).join('');
  res.send(renderPage('Analytics', '<div class="hero" style="padding:30px"><h1>School Analytics</h1></div><div class="grid"><div class="card"><h3>Fee Collection (6mo)</h3><canvas id="feeChart"></canvas></div><div class="card"><h3>Attendance by Class</h3><table><thead><tr><th>Class</th><th>Rate</th></tr></thead><tbody>' + attRows + '</tbody></table></div></div><div class="card"><h3>Top Performers</h3><table><thead><tr><th>Rank</th><th>Student</th><th>Class</th><th>Avg Score</th><th>Exams</th></tr></thead><tbody>' + topStudents.rows.map((r, i) => '<tr><td>' + (i + 1) + '</td><td>' + esc(r.name) + '</td><td>' + esc(r.class) + '</td><td class="badge badge-gold">' + Math.round(r.avg_score) + '</td><td>' + r.exams + '</td></tr>').join('') + '</tbody></table></div><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>new Chart(document.getElementById("feeChart"),{type:"line",data:{labels:' + JSON.stringify(feeLabels) + '},datasets:[{label:"UGX",data:' + JSON.stringify(feeData.rows.map(r => r.total)) + ',borderColor:"#3b82f6",tension:0.4,plugins:{legend:{display:false}}}]};)</script>', { tenant_name: req.tenant.name }, false, req.lang));
});

app.post('/webhook/whatsapp', checkDb, async (req, res) => {
  try {
    const msg = req.body.entry ? req.body.entry[0].changes[0].value.messages[0] : null;
    if (!msg) return res.sendStatus(200);
    const from = msg.from;
    const text = msg.text ? msg.text.body.toLowerCase() : '';
    let reply = "🤖 SSEWASSWA AI Bot\n\nCommands:\n• BALANCE [name]\n• ATTENDANCE [name]\n• FEES [name]\n• PAY";

    if (text.includes('balance') || text.includes('fee') || text.includes('bbanja')) {
      const nameMatch = text.match(/(?:balance|fee|bbanja)\s+(.+)/);
      if (nameMatch) {
        const name = nameMatch[1].trim();
        const s = await pool.query('SELECT name,balance,class FROM students WHERE LOWER(name) LIKE $1 LIMIT 1', ['%' + name + '%']);
        if (s.rows[0]) reply = "💰 *" + s.rows[0].name + "* (" + s.rows[0].class + ")\nBalance: UGX " + s.rows[0].balance.toLocaleString() + "\n\nReply PAY to settle via MoMo.";
        else reply = "❌ Student not found. Check spelling.";
      }
    } else if (text.includes('attendance') || text.includes('okujja')) {
      const nameMatch = text.match(/(?:attendance|okujja)\s+(.+)/);
      if (nameMatch) {
        const name = nameMatch[1].trim();
        const s = await pool.query('SELECT id,name FROM students WHERE LOWER(name) LIKE $1 LIMIT 1', ['%' + name + '%']);
        if (s.rows[0]) {
          const a = await pool.query("SELECT COUNT(*) FILTER (WHERE status='present') as p, COUNT(*) as t FROM attendance WHERE student_id=$1 AND date > NOW() - INTERVAL '30 days'", [s.rows[0].id]);
          const pct = a.rows[0].t > 0 ? Math.round((a.rows[0].p / a.rows[0].t) * 100) : 0;
          reply = "✅ " + s.rows[0].name + "\nAttendance: " + pct + "% (" + a.rows[0].p + "/" + a.rows[0].t + " days this month";
        }
      }
    } else if (text === 'pay' || text === 'sasula') {
      reply = "💳 To pay fees:\n1. Dial *165*3#\n2. Merchant Code: 123456\n2. Enter student name\n3. Enter amount";
    } else if (text === 'help' || text === 'obuyambi') {
      reply = "📚 How to use:\n1️⃣ BALANCE John Doe\n2️⃣ ATTENDANCE Mary Smith\n3️⃣ FEES Sarah\n\nReply HELP for more options.";
    }

    await sendWhatsApp(from, reply);
    res.sendStatus(200);
  } catch (e) { console.error('WA Error:', e.message); res.sendStatus(200); }
});

